9	use std::collections::HashMap;
10	use std::rc::Rc;
11	
12	use block2::RcBlock;
13	use futures::StreamExt as _;
14	use futures::channel::mpsc;
15	use gpui::{
16	    ForegroundExecutor, SharedString, SystemNotification, SystemNotificationAction,
17	    SystemNotificationResponse, Task,
18	};
19	use objc2::rc::Retained;
20	use objc2::runtime::{Bool, ProtocolObject};
21	use objc2::{AnyThread, DefinedClass, define_class, msg_send};
22	use objc2_foundation::{NSArray, NSBundle, NSError, NSObject, NSObjectProtocol, NSSet, NSString};
23	use objc2_user_notifications::{
